module.exports = [
{ e: "🌎", art: { b: "🌎", s: ["☀️", "🌙", "💧", "🌱"], c: ["#14466B", "#2C8AA0"] },
pt: { h: "O vovô chegou com um presente: um globo inflável, azul e verde, do tamanho de uma bola de praia. “Este é o nosso planeta, em miniatura”, disse. “Por 30 dias, vamos explorar a Terra inteira, de dentro para fora.” Leo jogou o globo para cima, e o Pipoca tentou pegá-lo no ar.", t: "Nossa casa no espaço", f: "A Terra é o terceiro planeta a partir do Sol. Ela existe há cerca de 4,5 bilhões de anos e é o único lugar do universo onde sabemos que existe vida. Tem ar para respirar, água líquida e a temperatura certinha para plantas, animais e pessoas.", x: "Cerca de 71% da superfície da Terra é coberta de água! Por isso, vista do espaço, ela parece uma bolinha azul.", s: ["A Terra não está nem perto demais nem longe demais do Sol, por isso a água não ferve nem congela toda.", "O ar que envolve a Terra protege o planeta e guarda o calor durante a noite.", "Somos mais de 8 bilhões de pessoas dividindo o mesmo planeta."], ex: { t: "Água ou terra?", m: "um globo inflável ou uma bola com um mapa desenhado, papel e lápis, um parceiro", p: ["Jogue a bola para alguém. Quem pegar olha onde está o seu dedão direito: na água ou na terra?", "Anote numa tabela e repitam umas 20 vezes.", "Contem: deu mais água ou mais terra? Quase sempre a água ganha, porque ela cobre a maior parte do planeta!"] }, at: "Passaporte do planeta", m: "papel dobrado como livrinho, lápis de cor", p: ["Faça um passaporte com seu nome, sua foto ou desenho e o título “Guardião do Planeta”.", "Na primeira página, desenhe a Terra vista do espaço.", "Carimbe ou desenhe o primeiro selo: “Dia 1: minha casa no espaço”."], q: "O que você mais gosta no nosso planeta?" },
en: { h: "Grandpa arrived with a present: an inflatable globe, blue and green, the size of a beach ball. “This is our planet in miniature,” he said. “For 30 days, we'll explore the whole Earth, inside and out.” Leo tossed the globe into the air, and Popcorn tried to catch it.", t: "Our home in space", f: "Earth is the third planet from the Sun. It's about 4.5 billion years old and it's the only place in the universe where we know life exists. It has air to breathe, liquid water and just the right temperature for plants, animals and people.", x: "About 71% of Earth's surface is covered with water! That's why, from space, it looks like a little blue marble.", s: ["Earth isn't too close to or too far from the Sun, so the water doesn't all boil away or freeze.", "The air surrounding Earth protects the planet and keeps it warm at night.", "More than 8 billion people share this one planet."], ex: { t: "Water or land?", m: "an inflatable globe or a ball with a map drawn on it, paper and pencil, a partner", p: ["Toss the ball to someone. Whoever catches it checks where their right thumb landed: water or land?", "Record it in a chart and repeat about 20 times.", "Count up: more water or more land? Water almost always wins, because it covers most of the planet!"] }, at: "Planet passport", m: "paper folded into a booklet, colored pencils", p: ["Make a passport with your name, your photo or a drawing of you and the title “Planet Guardian.”", "On the first page, draw Earth as seen from space.", "Stamp or draw your first stamp: “Day 1: my home in space.”"], q: "What do you like most about our planet?" },
es: { h: "El abuelo llegó con un regalo: un globo terráqueo inflable, azul y verde, del tamaño de una pelota de playa. “Este es nuestro planeta en miniatura”, dijo. “Durante 30 días vamos a explorar la Tierra entera, por dentro y por fuera.” Leo tiró el globo hacia arriba, y Palomita intentó atraparlo en el aire.", t: "Nuestra casa en el espacio", f: "La Tierra es el tercer planeta desde el Sol. Existe desde hace unos 4.500 millones de años y es el único lugar del universo donde sabemos que hay vida. Tiene aire para respirar, agua líquida y la temperatura justa para plantas, animales y personas.", x: "¡Cerca del 71% de la superficie de la Tierra está cubierta de agua! Por eso, vista desde el espacio, parece una canica azul.", s: ["La Tierra no está ni demasiado cerca ni demasiado lejos del Sol, por eso el agua no hierve ni se congela toda.", "El aire que rodea la Tierra protege al planeta y guarda el calor durante la noche.", "Somos más de 8.000 millones de personas compartiendo el mismo planeta."], ex: { t: "¿Agua o tierra?", m: "un globo inflable o una pelota con un mapa dibujado, papel y lápiz, un compañero", p: ["Tírale la pelota a alguien. Quien la atrape mira dónde quedó su pulgar derecho: ¿en el agua o en la tierra?", "Anótalo en una tabla y repitan unas 20 veces.", "Cuenten: ¿salió más agua o más tierra? ¡Casi siempre gana el agua, porque cubre la mayor parte del planeta!"] }, at: "Pasaporte del planeta", m: "papel doblado como librito, lápices de colores", p: ["Haz un pasaporte con tu nombre, tu foto o tu dibujo y el título “Guardián del Planeta”.", "En la primera página, dibuja la Tierra vista desde el espacio.", "Sella o dibuja el primer sello: “Día 1: mi casa en el espacio”."], q: "¿Qué es lo que más te gusta de nuestro planeta?" } },

{ e: "⚪", art: { b: "🌍", s: ["⛵", "📏", "🌞", "🏛️"], c: ["#0B3A5A", "#2C7AB0"] },
pt: { h: "Na praia, Leo viu um navio desaparecendo no horizonte, devagarinho, de baixo para cima. “Ele está afundando?”, perguntou assustado. “Não!”, riu o vovô. “Ele está indo para o outro lado da curva da Terra. É uma das pistas de que o nosso planeta é redondo.”", t: "A Terra é redonda", f: "Há mais de 2 mil anos, os gregos já sabiam que a Terra é redonda. Eles viam a sombra curva da Terra na Lua durante os eclipses e os navios sumindo no horizonte. Hoje, fotos tiradas do espaço mostram isso com clareza.", x: "Por volta de 240 antes de Cristo, o sábio grego Eratóstenes mediu o tamanho da Terra usando só sombras de varetas e matemática, e chegou bem perto do valor verdadeiro!", s: ["Uma volta completa ao redor da Terra, pela linha do Equador, tem uns 40 mil quilômetros.", "A Terra não é uma bola perfeita: ela é um pouquinho achatada nos polos.", "Os astronautas foram os primeiros a ver a Terra inteira, redondinha, com os próprios olhos."], ex: { t: "Navio sumindo no horizonte", m: "uma bola grande (o globo inflável), um barquinho ou bonequinho pequeno, massinha", p: ["Coloque a bola numa mesa, na altura dos seus olhos, e grude o barquinho em cima dela com massinha.", "Olhe para o barquinho de lado, bem na altura da bola, e vá girando a bola devagar, levando o barco para longe.", "Ele some primeiro por baixo e por último o topo, igualzinho aos navios no mar!"] }, at: "Pistas da Terra redonda", m: "papel, lápis de cor", p: ["Desenhe três pistas de que a Terra é redonda: o navio no horizonte, a sombra na Lua e a foto do espaço.", "Escreva embaixo de cada uma o que ela mostra.", "Desenhe o selo do dia 2 no seu passaporte."], q: "Como você explicaria para um amigo que a Terra é redonda?" },
en: { h: "At the beach, Leo watched a ship disappear over the horizon, slowly, from the bottom up. “Is it sinking?” he asked, alarmed. “No!” Grandpa laughed. “It's going around the curve of the Earth. That's one of the clues that our planet is round.”", t: "The Earth is round", f: "More than 2,000 years ago, the Greeks already knew Earth is round. They saw Earth's curved shadow on the Moon during eclipses and ships vanishing over the horizon. Today, photos taken from space show it clearly.", x: "Around 240 BC, the Greek scholar Eratosthenes measured the size of the Earth using only the shadows of sticks and math, and came very close to the real value!", s: ["Going all the way around Earth at the equator is about 40,000 kilometers (25,000 miles).", "Earth isn't a perfect ball: it's slightly flattened at the poles.", "Astronauts were the first people to see the whole round Earth with their own eyes."], ex: { t: "Ship over the horizon", m: "a big ball (the inflatable globe), a small toy boat or figure, play dough", p: ["Put the ball on a table at eye level and stick the boat on top with play dough.", "Look at the boat from the side, right at the level of the ball, and slowly turn the ball to carry the boat away.", "It disappears from the bottom first and the top last, just like ships at sea!"] }, at: "Clues of a round Earth", m: "paper, colored pencils", p: ["Draw three clues that Earth is round: the ship on the horizon, the shadow on the Moon and the photo from space.", "Under each one, write what it shows.", "Draw the day 2 stamp in your passport."], q: "How would you explain to a friend that Earth is round?" },
es: { h: "En la playa, Leo vio un barco desaparecer en el horizonte, despacito, de abajo hacia arriba. “¿Se está hundiendo?”, preguntó asustado. “¡No!”, se rió el abuelo. “Va hacia el otro lado de la curva de la Tierra. Es una de las pistas de que nuestro planeta es redondo.”", t: "La Tierra es redonda", f: "Hace más de 2.000 años, los griegos ya sabían que la Tierra es redonda. Veían la sombra curva de la Tierra en la Luna durante los eclipses y los barcos desapareciendo en el horizonte. Hoy, las fotos tomadas desde el espacio lo muestran claramente.", x: "¡Alrededor del año 240 antes de Cristo, el sabio griego Eratóstenes midió el tamaño de la Tierra usando solo sombras de varillas y matemática, y llegó muy cerca del valor real!", s: ["Una vuelta completa alrededor de la Tierra, por la línea del ecuador, mide unos 40.000 kilómetros.", "La Tierra no es una pelota perfecta: está un poquito achatada en los polos.", "Los astronautas fueron los primeros en ver la Tierra entera, redondita, con sus propios ojos."], ex: { t: "Barco que desaparece en el horizonte", m: "una pelota grande (el globo inflable), un barquito o muñequito pequeño, plastilina", p: ["Pon la pelota en una mesa, a la altura de tus ojos, y pega el barquito encima con plastilina.", "Mira el barquito de costado, justo a la altura de la pelota, y gira la pelota despacio, llevando el barco lejos.", "¡Desaparece primero por abajo y al final la punta, igualito que los barcos en el mar!"] }, at: "Pistas de la Tierra redonda", m: "papel, lápices de colores", p: ["Dibuja tres pistas de que la Tierra es redonda: el barco en el horizonte, la sombra en la Luna y la foto desde el espacio.", "Debajo de cada una escribe lo que muestra.", "Dibuja el sello del día 2 en tu pasaporte."], q: "¿Cómo le explicarías a un amigo que la Tierra es redonda?" } },

{ e: "🌗", art: { b: "🌗", s: ["☀️", "🌙", "⏰", "🛏️"], c: ["#1B1B4E", "#E0A02C"] },
pt: { h: "Leo ligou para a tia que mora no Japão e estranhou: aqui era de manhã, e lá ela já ia dormir! “Como pode ser noite lá e dia aqui ao mesmo tempo?”, perguntou. O vovô pegou a lanterna e o globo. “Porque a Terra gira como um pião”, explicou.", t: "Dia e noite", f: "A Terra gira em torno de si mesma, como um pião, e dá uma volta completa a cada 24 horas, mais ou menos. O lado virado para o Sol fica de dia, e o lado de costas para o Sol fica de noite. Esse giro se chama rotação.", x: "Na linha do Equador, a Terra gira a uns 1.670 quilômetros por hora, mais rápido que um avião! Não sentimos porque tudo à nossa volta, inclusive o ar, gira junto.", s: ["O Sol não “anda” pelo céu: é a Terra que gira, e por isso parece que ele nasce e se põe.", "O Sol nasce no leste e se põe no oeste.", "Quando é dia no Brasil, é noite em países do outro lado do mundo, como o Japão."], ex: { t: "Lanterna e globo", m: "o globo ou uma laranja, um adesivo pequeno, uma lanterna, um quarto escuro", p: ["Cole o adesivo no lugar onde fica o Brasil.", "No quarto escuro, a lanterna parada é o Sol. Ilumine o globo e gire-o devagar.", "Veja o adesivo passar do dia para a noite e de novo para o dia. Uma volta completa é um dia inteiro!"] }, at: "Relógio do mundo", m: "papel, lápis de cor", p: ["Desenhe dois relógios: um do Brasil e um do Japão.", "Em um, desenhe uma criança tomando café da manhã; no outro, uma criança indo dormir.", "Desenhe o selo do dia 3 no passaporte."], q: "O que você faria se o dia durasse 48 horas?" },
en: { h: "Leo called his aunt who lives in Japan and was confused: here it was morning, and there she was about to go to bed! “How can it be night there and day here at the same time?” he asked. Grandpa grabbed the flashlight and the globe. “Because the Earth spins like a top,” he explained.", t: "Day and night", f: "Earth spins around itself like a top, making one full turn about every 24 hours. The side facing the Sun has day, and the side facing away has night. This spinning is called rotation.", x: "At the equator, Earth spins at about 1,670 kilometers per hour (1,000 mph), faster than an airplane! We don't feel it because everything around us, including the air, spins along with us.", s: ["The Sun doesn't “move” across the sky: Earth turns, which makes it look like the Sun rises and sets.", "The Sun rises in the east and sets in the west.", "When it's daytime in Brazil, it's nighttime in countries on the other side of the world, like Japan."], ex: { t: "Flashlight and globe", m: "the globe or an orange, a small sticker, a flashlight, a dark room", p: ["Put the sticker where you live.", "In the dark room, the still flashlight is the Sun. Shine it on the globe and turn the globe slowly.", "Watch the sticker go from day to night and back to day. One full turn is one whole day!"] }, at: "World clock", m: "paper, colored pencils", p: ["Draw two clocks: one for where you live and one for Japan.", "In one, draw a kid eating breakfast; in the other, a kid going to bed.", "Draw the day 3 stamp in your passport."], q: "What would you do if a day lasted 48 hours?" },
es: { h: "Leo llamó a su tía que vive en Japón y se extrañó: ¡aquí era de mañana y allá ella ya se iba a dormir! “¿Cómo puede ser de noche allá y de día aquí al mismo tiempo?”, preguntó. El abuelo tomó la linterna y el globo. “Porque la Tierra gira como un trompo”, explicó.", t: "El día y la noche", f: "La Tierra gira sobre sí misma, como un trompo, y da una vuelta completa cada 24 horas, más o menos. El lado que mira al Sol tiene día, y el lado de espaldas al Sol tiene noche. Ese giro se llama rotación.", x: "¡En la línea del ecuador, la Tierra gira a unos 1.670 kilómetros por hora, más rápido que un avión! No lo sentimos porque todo a nuestro alrededor, incluso el aire, gira con nosotros.", s: ["El Sol no “camina” por el cielo: es la Tierra la que gira, y por eso parece que sale y se pone.", "El Sol sale por el este y se pone por el oeste.", "Cuando es de día en América, es de noche en países del otro lado del mundo, como Japón."], ex: { t: "Linterna y globo", m: "el globo o una naranja, un sticker pequeño, una linterna, un cuarto oscuro", p: ["Pega el sticker donde vives.", "En el cuarto oscuro, la linterna quieta es el Sol. Ilumina el globo y gíralo despacio.", "Mira cómo el sticker pasa del día a la noche y otra vez al día. ¡Una vuelta completa es un día entero!"] }, at: "Reloj del mundo", m: "papel, lápices de colores", p: ["Dibuja dos relojes: uno de donde vives y uno de Japón.", "En uno dibuja un niño desayunando; en el otro, un niño yéndose a dormir.", "Dibuja el sello del día 3 en el pasaporte."], q: "¿Qué harías si el día durara 48 horas?" } },

{ e: "🎂", art: { b: "☀️", s: ["🌍", "🎂", "📅", "🔄"], c: ["#4E3A0B", "#E0A02C"] },
pt: { h: "No aniversário da Nina, o vovô colocou uma lâmpada no meio da sala e pediu para ela dar oito voltas em torno dela. “Por quê?”, perguntou Nina, rindo. “Porque você tem 8 anos”, disse o vovô. “E cada ano é uma volta completa da Terra ao redor do Sol!”", t: "A volta ao redor do Sol", f: "Além de girar como um pião, a Terra também viaja em volta do Sol. Uma volta completa leva cerca de 365 dias e um quarto: é um ano. Esse caminho se chama órbita, e esse movimento se chama translação.", x: "A Terra viaja ao redor do Sol a mais de 100 mil quilômetros por hora! Mesmo assim, a viagem completa leva um ano inteiro, porque o caminho é enorme.", s: ["Como cada ano tem 365 dias e mais umas 6 horas, a cada 4 anos juntamos essas horas num dia extra: o 29 de fevereiro, nos anos bissextos.", "A Terra fica a uns 150 milhões de quilômetros do Sol.", "A luz do Sol leva cerca de 8 minutos para chegar até nós."], ex: { t: "Dança do Sol e da Terra", m: "uma luminária ou lanterna no meio da sala (o Sol), espaço para andar, um adulto", p: ["Uma pessoa segura a lanterna no meio da sala: é o Sol.", "Você é a Terra: ande em círculo ao redor do Sol, girando devagar no seu próprio corpo enquanto anda.", "Cada giro no corpo é um dia, e cada volta completa na sala é um ano. Que tontura, hein?"] }, at: "Minhas voltas ao Sol", m: "papel, lápis de cor", p: ["Desenhe o Sol no meio e círculos em volta, um para cada ano da sua vida.", "Em cada círculo, desenhe algo importante que aconteceu naquele ano.", "Desenhe o selo do dia 4 no passaporte."], q: "Quantas voltas ao Sol você já deu? E seus avós?" },
en: { h: "On Nina's birthday, Grandpa put a lamp in the middle of the living room and asked her to walk around it eight times. “Why?” Nina asked, laughing. “Because you're 8,” Grandpa said. “And every year is one full trip of the Earth around the Sun!”", t: "The trip around the Sun", f: "Besides spinning like a top, Earth also travels around the Sun. One full trip takes about 365 and a quarter days: that's a year. The path is called an orbit, and this motion is called revolution.", x: "Earth travels around the Sun at more than 100,000 kilometers per hour (67,000 mph)! Even so, the full trip takes a whole year because the path is enormous.", s: ["Because each year has 365 days plus about 6 hours, every 4 years we gather those hours into an extra day: February 29, in leap years.", "Earth is about 150 million kilometers (93 million miles) from the Sun.", "Sunlight takes about 8 minutes to reach us."], ex: { t: "The Sun and Earth dance", m: "a lamp or flashlight in the middle of the room (the Sun), space to walk, a grown-up", p: ["One person holds the flashlight in the middle of the room: that's the Sun.", "You're the Earth: walk in a circle around the Sun, slowly spinning your body as you go.", "Each spin of your body is a day, and each full lap around the room is a year. Dizzy yet?"] }, at: "My trips around the Sun", m: "paper, colored pencils", p: ["Draw the Sun in the middle and circles around it, one for each year of your life.", "In each circle, draw something important that happened that year.", "Draw the day 4 stamp in your passport."], q: "How many trips around the Sun have you taken? And your grandparents?" },
es: { h: "En el cumpleaños de Nina, el abuelo puso una lámpara en el medio de la sala y le pidió que diera ocho vueltas alrededor de ella. “¿Por qué?”, preguntó Nina, riéndose. “Porque tienes 8 años”, dijo el abuelo. “¡Y cada año es una vuelta completa de la Tierra alrededor del Sol!”", t: "La vuelta alrededor del Sol", f: "Además de girar como un trompo, la Tierra también viaja alrededor del Sol. Una vuelta completa tarda unos 365 días y un cuarto: es un año. Ese camino se llama órbita, y ese movimiento se llama traslación.", x: "¡La Tierra viaja alrededor del Sol a más de 100.000 kilómetros por hora! Aun así, el viaje completo tarda un año entero, porque el camino es enorme.", s: ["Como cada año tiene 365 días y unas 6 horas más, cada 4 años juntamos esas horas en un día extra: el 29 de febrero, en los años bisiestos.", "La Tierra está a unos 150 millones de kilómetros del Sol.", "La luz del Sol tarda unos 8 minutos en llegar hasta nosotros."], ex: { t: "Baile del Sol y la Tierra", m: "una lámpara o linterna en el medio de la sala (el Sol), espacio para caminar, un adulto", p: ["Una persona sostiene la linterna en el medio de la sala: es el Sol.", "Tú eres la Tierra: camina en círculo alrededor del Sol, girando despacio sobre ti mismo mientras caminas.", "Cada giro de tu cuerpo es un día, y cada vuelta completa a la sala es un año. ¿Qué mareo, no?"] }, at: "Mis vueltas al Sol", m: "papel, lápices de colores", p: ["Dibuja el Sol en el medio y círculos alrededor, uno por cada año de tu vida.", "En cada círculo, dibuja algo importante que pasó ese año.", "Dibuja el sello del día 4 en el pasaporte."], q: "¿Cuántas vueltas al Sol diste ya? ¿Y tus abuelos?" } },

{ e: "🍂", art: { b: "🍂", s: ["❄️", "🌸", "☀️", "🌍"], c: ["#5A2A0B", "#E07A2C"] },
pt: { h: "Leo viu um filme de Natal com neve e bonecos de neve, e reclamou: “Por que aqui o Natal é no calorão?”. O vovô riu e inclinou o globo. “Porque a Terra é tortinha!”, disse. “E quando lá em cima é inverno, aqui embaixo é verão.”", t: "As estações do ano", f: "O eixo da Terra é inclinado. Por isso, durante a viagem em volta do Sol, ora o hemisfério norte recebe a luz mais de frente, ora é o hemisfério sul. Quem recebe a luz mais de frente tem verão; quem recebe mais de lado tem inverno. Entre eles vêm a primavera e o outono.", x: "Quando é verão no Brasil, é inverno nos Estados Unidos e na Europa! Por isso o Natal brasileiro é no calor, e o de lá é no frio.", s: ["As estações não acontecem porque a Terra fica mais perto ou mais longe do Sol, e sim por causa da inclinação.", "Perto da linha do Equador, como na Amazônia, faz calor o ano todo, e as estações são mais de chuva e de seca.", "Nos polos, o inverno tem dias em que o Sol nem aparece, e o verão tem dias em que ele nem se põe!"], ex: { t: "Luz reta e luz torta", m: "uma lanterna, uma folha de papel, um lápis", p: ["Aponte a lanterna bem reta para o papel e contorne a mancha de luz com o lápis.", "Agora incline a lanterna, sem mudar a distância, e contorne a nova mancha.", "A mancha inclinada é maior e mais fraquinha! A mesma luz se espalha mais e esquenta menos. É assim no inverno."] }, at: "Árvore das quatro estações", m: "papel, lápis de cor", p: ["Divida o papel em quatro e desenhe a mesma árvore em cada parte.", "Pinte uma com flores (primavera), uma cheia de frutas e sol (verão), uma com folhas caindo (outono) e uma pelada ou com frio (inverno).", "Desenhe o selo do dia 5 no passaporte."], q: "Qual estação do ano você prefere? Por quê?" },
en: { h: "Leo watched a Christmas movie with snow and snowmen and complained, “Why is Christmas so hot here?” Grandpa laughed and tilted the globe. “Because Earth is a little crooked!” he said. “And when it's winter up north, it's summer down south.”", t: "The seasons", f: "Earth's axis is tilted. So, during its trip around the Sun, sometimes the Northern Hemisphere gets sunlight more directly and sometimes the Southern Hemisphere does. Whoever gets the more direct light has summer; whoever gets slanted light has winter. Spring and fall come in between.", x: "When it's summer in Brazil, it's winter in the United States and Europe! That's why Christmas in Brazil is hot, while up north it's cold.", s: ["Seasons don't happen because Earth gets closer to or farther from the Sun, but because of the tilt.", "Near the equator, like in the Amazon, it's warm all year, and the seasons are more about rain and dry spells.", "At the poles, winter has days when the Sun doesn't come up at all, and summer has days when it never sets!"], ex: { t: "Straight light and slanted light", m: "a flashlight, a sheet of paper, a pencil", p: ["Point the flashlight straight down at the paper and trace around the spot of light.", "Now tilt the flashlight without changing the distance and trace the new spot.", "The slanted spot is bigger and dimmer! The same light spreads out more and warms less. That's what happens in winter."] }, at: "Four-seasons tree", m: "paper, colored pencils", p: ["Divide the paper into four and draw the same tree in each part.", "Color one with flowers (spring), one full of fruit and sun (summer), one with falling leaves (fall) and one bare and chilly (winter).", "Draw the day 5 stamp in your passport."], q: "Which season do you like best? Why?" },
es: { h: "Leo vio una película de Navidad con nieve y muñecos de nieve, y se quejó: “¿Por qué aquí la Navidad es con tanto calor?”. El abuelo se rió e inclinó el globo. “¡Porque la Tierra está torcidita!”, dijo. “Y cuando arriba es invierno, aquí abajo es verano.”", t: "Las estaciones del año", f: "El eje de la Tierra está inclinado. Por eso, durante el viaje alrededor del Sol, a veces el hemisferio norte recibe la luz más de frente y a veces el hemisferio sur. Quien recibe la luz más de frente tiene verano; quien la recibe más de costado tiene invierno. Entre ellos vienen la primavera y el otoño.", x: "¡Cuando es verano en Sudamérica, es invierno en Estados Unidos y Europa! Por eso la Navidad en el sur es con calor, y en el norte es con frío.", s: ["Las estaciones no ocurren porque la Tierra esté más cerca o más lejos del Sol, sino por la inclinación.", "Cerca de la línea del ecuador, como en la Amazonía, hace calor todo el año, y las estaciones son más de lluvia y de sequía.", "¡En los polos, el invierno tiene días en que el Sol ni aparece, y el verano tiene días en que nunca se pone!"], ex: { t: "Luz derecha y luz torcida", m: "una linterna, una hoja de papel, un lápiz", p: ["Apunta la linterna bien derecha hacia el papel y marca el contorno de la mancha de luz con el lápiz.", "Ahora inclina la linterna, sin cambiar la distancia, y marca la nueva mancha.", "¡La mancha inclinada es más grande y más débil! La misma luz se reparte más y calienta menos. Así pasa en invierno."] }, at: "Árbol de las cuatro estaciones", m: "papel, lápices de colores", p: ["Divide el papel en cuatro y dibuja el mismo árbol en cada parte.", "Pinta uno con flores (primavera), uno lleno de frutas y sol (verano), uno con hojas cayendo (otoño) y uno pelado o con frío (invierno).", "Dibuja el sello del día 5 en el pasaporte."], q: "¿Qué estación del año prefieres? ¿Por qué?" } },

{ e: "🌙", art: { b: "🌙", s: ["🌑", "🌓", "🌕", "🌊"], c: ["#1B1B3A", "#5A5A8A"] },
pt: { h: "Numa noite de lua cheia, Nina e Leo foram para a varanda. “Ontem ela estava mais magrinha”, reparou Nina. “A Lua não muda de tamanho”, disse o vovô. “É a parte iluminada pelo Sol que a gente consegue ver que muda.” Ele trouxe biscoitos recheados para explicar.", t: "A Lua, nossa companheira", f: "A Lua gira em volta da Terra e leva cerca de 29 dias e meio para passar por todas as fases: nova, crescente, cheia e minguante. Ela não tem luz própria: brilha porque reflete a luz do Sol. A Lua também puxa a água dos oceanos e ajuda a criar as marés.", x: "A Lua sempre mostra a mesma face para a Terra! Só conseguimos ver o outro lado dela por fotos tiradas por naves espaciais.", s: ["A Lua fica a cerca de 384 mil quilômetros da Terra.", "Muitos cientistas acham que a Lua se formou quando um objeto do tamanho de um planeta se chocou com a Terra, há bilhões de anos.", "As pegadas dos astronautas que pisaram na Lua continuam lá, porque não há vento."], ex: { t: "Fases da Lua de biscoito", m: "8 biscoitos recheados (de recheio branco), uma colher, um papel com um círculo grande desenhado", p: ["Abra os biscoitos com cuidado, deixando o recheio só de um lado.", "Com a colher, raspe o recheio de cada um para formar as fases: nova (sem recheio), crescente, quarto crescente, cheia e assim por diante.", "Arrume os biscoitos em volta do círculo, na ordem. Depois pode comer a lua toda!"] }, at: "Diário da Lua", m: "caderno, lápis", p: ["Durante uma semana, olhe a Lua toda noite (ou de dia, às vezes ela aparece!).", "Desenhe o formato dela a cada dia e anote a data.", "Desenhe o selo do dia 6 no passaporte."], q: "Se você pudesse visitar a Lua, o que levaria na mochila?" },
en: { h: "On a full-moon night, Nina and Leo went out to the balcony. “Yesterday it was skinnier,” Nina noticed. “The Moon doesn't change size,” said Grandpa. “What changes is how much of the sunlit part we can see.” He brought out sandwich cookies to explain.", t: "The Moon, our companion", f: "The Moon travels around the Earth and takes about 29 and a half days to go through all its phases: new, waxing, full and waning. It doesn't make its own light: it shines because it reflects sunlight. The Moon also pulls on the oceans and helps create the tides.", x: "The Moon always shows the same face to Earth! We can only see its far side in photos taken by spacecraft.", s: ["The Moon is about 384,000 kilometers (239,000 miles) from Earth.", "Many scientists think the Moon formed when a planet-sized object crashed into Earth billions of years ago.", "The footprints of the astronauts who walked on the Moon are still there, because there's no wind."], ex: { t: "Cookie Moon phases", m: "8 sandwich cookies (with white filling), a spoon, a paper with a big circle drawn on it", p: ["Carefully twist the cookies open, leaving the filling on one side.", "With the spoon, scrape the filling on each one to make the phases: new (no filling), waxing crescent, first quarter, full and so on.", "Arrange the cookies around the circle in order. Then you can eat the whole Moon!"] }, at: "Moon diary", m: "notebook, pencil", p: ["For a week, look at the Moon every night (or during the day; sometimes it shows up!).", "Draw its shape each day and write the date.", "Draw the day 6 stamp in your passport."], q: "If you could visit the Moon, what would you pack in your backpack?" },
es: { h: "Una noche de luna llena, Nina y Leo salieron al balcón. “Ayer estaba más flaquita”, notó Nina. “La Luna no cambia de tamaño”, dijo el abuelo. “Lo que cambia es la parte iluminada por el Sol que podemos ver.” Trajo galletitas rellenas para explicarlo.", t: "La Luna, nuestra compañera", f: "La Luna gira alrededor de la Tierra y tarda unos 29 días y medio en pasar por todas sus fases: nueva, creciente, llena y menguante. No tiene luz propia: brilla porque refleja la luz del Sol. La Luna también atrae el agua de los océanos y ayuda a formar las mareas.", x: "¡La Luna siempre le muestra la misma cara a la Tierra! Solo podemos ver su otro lado en fotos tomadas por naves espaciales.", s: ["La Luna está a unos 384.000 kilómetros de la Tierra.", "Muchos científicos creen que la Luna se formó cuando un objeto del tamaño de un planeta chocó con la Tierra hace miles de millones de años.", "Las huellas de los astronautas que pisaron la Luna siguen allí, porque no hay viento."], ex: { t: "Fases de la Luna con galletitas", m: "8 galletitas rellenas (de relleno blanco), una cuchara, un papel con un círculo grande dibujado", p: ["Abre las galletitas con cuidado, dejando el relleno de un solo lado.", "Con la cuchara, raspa el relleno de cada una para formar las fases: nueva (sin relleno), creciente, cuarto creciente, llena y así.", "Ordena las galletitas alrededor del círculo. ¡Después puedes comerte toda la Luna!"] }, at: "Diario de la Luna", m: "cuaderno, lápiz", p: ["Durante una semana, mira la Luna cada noche (¡o de día, a veces aparece!).", "Dibuja su forma cada día y anota la fecha.", "Dibuja el sello del día 6 en el pasaporte."], q: "Si pudieras visitar la Luna, ¿qué llevarías en la mochila?" } },

{ e: "🥚", art: { b: "🥚", s: ["🔥", "🌋", "⛏️", "🌍"], c: ["#5A1B0B", "#E0602C"] },
pt: { h: "No café da manhã, o vovô cortou um ovo cozido ao meio e mostrou para Nina e Leo. “Este ovo é um ótimo modelo da Terra”, disse. “A casca é fininha, a clara é grossa, e a gema fica no centro, bem quentinha.” Leo nunca mais olhou para um ovo do mesmo jeito.", t: "As camadas da Terra", f: "A Terra tem camadas, como uma cebola. Por fora fica a crosta, onde vivemos, que é fininha. Embaixo vem o manto, de rocha muito quente que se move devagar. No centro fica o núcleo, feito principalmente de ferro e níquel: a parte de fora é líquida e a de dentro é sólida.", x: "O centro da Terra é tão quente quanto a superfície do Sol, com mais de 5 mil graus! O buraco mais fundo já cavado pelos humanos tem só uns 12 quilômetros, nem chegou perto do manto.", s: ["Se a Terra fosse uma maçã, a crosta seria mais fina que a casquinha dela.", "O núcleo de metal em movimento é o que transforma a Terra num grande ímã.", "Os cientistas estudam o interior da Terra pelas ondas dos terremotos, que mudam de jeito em cada camada."], ex: { t: "Terra de massinha", m: "massinha de 4 cores, uma faca de plástico, um adulto", p: ["Faça uma bolinha amarela (núcleo interno) e cubra com uma camada laranja (núcleo externo).", "Cubra com uma camada grossa vermelha (manto) e, por fim, uma camada bem fina azul e verde (crosta).", "Com um adulto, corte a bola ao meio: você verá todas as camadas da Terra!"] }, at: "Viagem ao centro da Terra", m: "papel, lápis de cor", p: ["Desenhe a Terra cortada ao meio com as camadas coloridas.", "Desenhe um elevador imaginário descendo até o centro e escreva o nome de cada parada.", "Desenhe o selo do dia 7 no passaporte."], q: "O que você imagina que encontraria se pudesse cavar até o centro da Terra?" },
en: { h: "At breakfast, Grandpa cut a hard-boiled egg in half and showed it to Nina and Leo. “This egg is a great model of the Earth,” he said. “The shell is thin, the white is thick and the yolk sits in the center, nice and hot.” Leo never looked at an egg the same way again.", t: "Earth's layers", f: "Earth has layers, like an onion. On the outside is the crust, where we live, which is very thin. Below it is the mantle, made of extremely hot rock that moves slowly. At the center is the core, made mostly of iron and nickel: the outer part is liquid and the inner part is solid.", x: "Earth's center is as hot as the surface of the Sun, more than 5,000 degrees Celsius! The deepest hole humans have ever dug is only about 12 kilometers (7.5 miles) deep, nowhere near the mantle.", s: ["If Earth were an apple, the crust would be thinner than its skin.", "The moving metal core is what turns Earth into a giant magnet.", "Scientists study Earth's interior through earthquake waves, which behave differently in each layer."], ex: { t: "Play dough Earth", m: "play dough in 4 colors, a plastic knife, a grown-up", p: ["Make a small yellow ball (inner core) and cover it with an orange layer (outer core).", "Cover that with a thick red layer (mantle) and finally a very thin blue and green layer (crust).", "With a grown-up, cut the ball in half: you'll see all of Earth's layers!"] }, at: "Journey to the center of the Earth", m: "paper, colored pencils", p: ["Draw the Earth cut in half with the colored layers.", "Draw an imaginary elevator going down to the center and write the name of each stop.", "Draw the day 7 stamp in your passport."], q: "What do you imagine you'd find if you could dig to the center of the Earth?" },
es: { h: "En el desayuno, el abuelo cortó un huevo duro por la mitad y se lo mostró a Nina y Leo. “Este huevo es un muy buen modelo de la Tierra”, dijo. “La cáscara es finita, la clara es gruesa y la yema está en el centro, bien calentita.” Leo nunca más miró un huevo de la misma forma.", t: "Las capas de la Tierra", f: "La Tierra tiene capas, como una cebolla. Por fuera está la corteza, donde vivimos, que es muy finita. Debajo está el manto, de roca muy caliente que se mueve despacio. En el centro está el núcleo, hecho sobre todo de hierro y níquel: la parte de afuera es líquida y la de adentro es sólida.", x: "¡El centro de la Tierra es tan caliente como la superficie del Sol, con más de 5.000 grados! El pozo más profundo que cavaron los humanos tiene solo unos 12 kilómetros, ni se acercó al manto.", s: ["Si la Tierra fuera una manzana, la corteza sería más fina que su cáscara.", "El núcleo de metal en movimiento es lo que convierte a la Tierra en un gran imán.", "Los científicos estudian el interior de la Tierra con las ondas de los terremotos, que cambian en cada capa."], ex: { t: "Tierra de plastilina", m: "plastilina de 4 colores, un cuchillo de plástico, un adulto", p: ["Haz una bolita amarilla (núcleo interno) y cúbrela con una capa naranja (núcleo externo).", "Cúbrela con una capa gruesa roja (manto) y, al final, una capa muy finita azul y verde (corteza).", "Con un adulto, corta la bola por la mitad: ¡verás todas las capas de la Tierra!"] }, at: "Viaje al centro de la Tierra", m: "papel, lápices de colores", p: ["Dibuja la Tierra cortada por la mitad con las capas de colores.", "Dibuja un ascensor imaginario bajando hasta el centro y escribe el nombre de cada parada.", "Dibuja el sello del día 7 en el pasaporte."], q: "¿Qué imaginas que encontrarías si pudieras cavar hasta el centro de la Tierra?" } },

{ e: "🧩", art: { b: "🧩", s: ["🌎", "🌍", "🐢", "📏"], c: ["#1B4E3A", "#3AA07A"] },
pt: { h: "Leo estava montando um quebra-cabeça do mapa-múndi e reparou que a ponta do Brasil se encaixava direitinho no lado da África. “Olha, Nina! Parece que eles estavam grudados!”, gritou. O vovô ficou orgulhoso: “Você acabou de notar o que um cientista famoso notou há mais de cem anos.”", t: "Os continentes que andam", f: "A crosta da Terra é dividida em pedaços enormes, chamados placas tectônicas, que flutuam devagar sobre o manto. Há uns 200 milhões de anos, todos os continentes estavam juntos num supercontinente chamado Pangeia. Aos poucos, eles foram se separando.", x: "Os continentes se movem mais ou menos na mesma velocidade em que as nossas unhas crescem: alguns centímetros por ano! O Oceano Atlântico fica um pouquinho mais largo a cada ano.", s: ["O cientista alemão Alfred Wegener propôs a ideia dos continentes que se movem em 1912, mas muita gente não acreditou nele por anos.", "Fósseis dos mesmos animais e plantas antigos foram encontrados no Brasil e na África, uma pista de que eles já estiveram juntos.", "Quando duas placas se empurram, podem formar montanhas, vulcões e terremotos."], ex: { t: "Quebra-cabeça da Pangeia", m: "um mapa-múndi impresso, tesoura, cola, uma folha grande", p: ["Recorte os continentes do mapa, seguindo o contorno da costa.", "Tente encaixá-los como um quebra-cabeça, começando pela América do Sul e pela África.", "Cole sua Pangeia na folha grande. Quais continentes se encaixaram melhor?"] }, at: "A Terra do futuro", m: "papel, lápis de cor", p: ["Imagine como os continentes vão estar daqui a milhões de anos.", "Desenhe um mapa inventado do futuro e dê um nome ao novo supercontinente.", "Desenhe o selo do dia 8 no passaporte."], q: "Que nome você daria a um supercontinente do futuro?" },
en: { h: "Leo was doing a world map puzzle and noticed that the tip of Brazil fit perfectly into the side of Africa. “Look, Nina! It's like they used to be stuck together!” he shouted. Grandpa was proud: “You just noticed what a famous scientist noticed more than a hundred years ago.”", t: "Continents on the move", f: "Earth's crust is split into enormous pieces called tectonic plates, which slowly drift on the mantle. About 200 million years ago, all the continents were joined in a supercontinent called Pangaea. Little by little, they drifted apart.", x: "Continents move at about the same speed your fingernails grow: a few centimeters a year! The Atlantic Ocean gets a tiny bit wider every year.", s: ["German scientist Alfred Wegener proposed the idea of moving continents in 1912, but many people didn't believe him for years.", "Fossils of the same ancient animals and plants have been found in Brazil and Africa, a clue that they were once joined.", "When two plates push against each other, they can form mountains, volcanoes and earthquakes."], ex: { t: "Pangaea puzzle", m: "a printed world map, scissors, glue, a large sheet of paper", p: ["Cut out the continents from the map, following the coastlines.", "Try to fit them together like a puzzle, starting with South America and Africa.", "Glue your Pangaea onto the large sheet. Which continents fit best?"] }, at: "Earth of the future", m: "paper, colored pencils", p: ["Imagine how the continents will look millions of years from now.", "Draw a made-up map of the future and name the new supercontinent.", "Draw the day 8 stamp in your passport."], q: "What would you name a supercontinent of the future?" },
es: { h: "Leo estaba armando un rompecabezas del mapamundi y notó que la punta de Brasil encajaba justito en el costado de África. “¡Mira, Nina! ¡Parece que estaban pegados!”, gritó. El abuelo se puso orgulloso: “Acabas de notar lo que notó un científico famoso hace más de cien años.”", t: "Los continentes que se mueven", f: "La corteza de la Tierra está dividida en pedazos enormes, llamados placas tectónicas, que flotan despacio sobre el manto. Hace unos 200 millones de años, todos los continentes estaban juntos en un supercontinente llamado Pangea. Poco a poco se fueron separando.", x: "¡Los continentes se mueven más o menos a la misma velocidad a la que crecen nuestras uñas: unos centímetros por año! El océano Atlántico se hace un poquito más ancho cada año.", s: ["El científico alemán Alfred Wegener propuso la idea de los continentes que se mueven en 1912, pero mucha gente no le creyó durante años.", "Se encontraron fósiles de los mismos animales y plantas antiguos en Brasil y en África, una pista de que estuvieron juntos.", "Cuando dos placas se empujan, pueden formar montañas, volcanes y terremotos."], ex: { t: "Rompecabezas de Pangea", m: "un mapamundi impreso, tijera, pegamento, una hoja grande", p: ["Recorta los continentes del mapa, siguiendo el contorno de la costa.", "Intenta encajarlos como un rompecabezas, empezando por América del Sur y África.", "Pega tu Pangea en la hoja grande. ¿Qué continentes encajaron mejor?"] }, at: "La Tierra del futuro", m: "papel, lápices de colores", p: ["Imagina cómo estarán los continentes dentro de millones de años.", "Dibuja un mapa inventado del futuro y ponle nombre al nuevo supercontinente.", "Dibuja el sello del día 8 en el pasaporte."], q: "¿Qué nombre le pondrías a un supercontinente del futuro?" } },

{ e: "🏚️", art: { b: "🏚️", s: ["📈", "🧱", "🌍", "🆘"], c: ["#3A2A1B", "#8A6A4A"] },
pt: { h: "Nina viu na TV um prédio balançando num terremoto em outro país e perguntou se isso podia acontecer na casa deles. O vovô explicou: “No Brasil quase não temos terremotos fortes, porque estamos no meio de uma placa. Mas em lugares na borda das placas, eles acontecem bastante.”", t: "Terremotos", f: "As placas tectônicas não deslizam lisinhas: às vezes elas travam umas nas outras. A pressão vai aumentando até que, de repente, elas se soltam, e o chão treme. Isso é um terremoto. Os cientistas medem os terremotos com aparelhos chamados sismógrafos.", x: "Acontecem milhares de terremotos no mundo todos os dias, mas a grande maioria é tão fraquinha que ninguém sente!", s: ["Países como Japão, Chile e México ficam na borda de placas e têm muitos terremotos.", "Por isso eles constroem prédios especiais, que balançam sem cair.", "Quando um terremoto acontece no fundo do mar, ele pode criar ondas gigantes chamadas tsunamis."], ex: { t: "Terremoto na gelatina", m: "uma forma com gelatina firme, cubinhos de açúcar ou peças de montar, palitos de dente", p: ["Construa pequenas casinhas com cubinhos de açúcar ou peças em cima da gelatina.", "Balance a forma de leve de um lado para o outro, como um terremoto.", "Quais casinhas caíram? Agora tente construções mais largas e baixas ou com palitos cruzados. Elas aguentam melhor?"] }, at: "Plano de segurança", m: "papel, lápis de cor", p: ["Desenhe sua casa e marque o lugar mais seguro de cada cômodo, como debaixo de uma mesa forte.", "Escreva as três regras para terremotos: abaixar, cobrir a cabeça e se segurar.", "Desenhe o selo do dia 9 no passaporte."], q: "Como você acha que as pessoas que moram onde tem terremotos se preparam?" },
en: { h: "Nina saw a building shaking on TV during an earthquake in another country and asked if that could happen at their house. Grandpa explained, “Brazil has hardly any strong earthquakes because it's in the middle of a plate. But near the edges of the plates, they happen quite a lot.”", t: "Earthquakes", f: "Tectonic plates don't slide smoothly: sometimes they get stuck on each other. Pressure builds until, suddenly, they slip, and the ground shakes. That's an earthquake. Scientists measure earthquakes with instruments called seismographs.", x: "Thousands of earthquakes happen around the world every day, but the vast majority are so weak that no one feels them!", s: ["Countries like Japan, Chile and Mexico sit on plate edges and have many earthquakes.", "That's why they build special buildings that sway without falling down.", "When an earthquake happens under the sea, it can create giant waves called tsunamis."], ex: { t: "Jelly earthquake", m: "a pan of firm gelatin, sugar cubes or building blocks, toothpicks", p: ["Build little houses out of sugar cubes or blocks on top of the gelatin.", "Gently shake the pan from side to side, like an earthquake.", "Which houses fell? Now try wider, lower buildings or ones braced with crossed toothpicks. Do they hold up better?"] }, at: "Safety plan", m: "paper, colored pencils", p: ["Draw your home and mark the safest spot in each room, like under a sturdy table.", "Write the three earthquake rules: drop, cover your head and hold on.", "Draw the day 9 stamp in your passport."], q: "How do you think people who live in earthquake areas get prepared?" },
es: { h: "Nina vio en la tele un edificio sacudiéndose por un terremoto en otro país y preguntó si eso podía pasar en su casa. El abuelo explicó: “En Brasil casi no hay terremotos fuertes, porque estamos en el medio de una placa. Pero en lugares en el borde de las placas, pasan bastante.”", t: "Terremotos", f: "Las placas tectónicas no se deslizan lisitas: a veces se traban unas con otras. La presión va aumentando hasta que, de repente, se sueltan, y el suelo tiembla. Eso es un terremoto. Los científicos miden los terremotos con aparatos llamados sismógrafos.", x: "¡En el mundo ocurren miles de terremotos todos los días, pero la gran mayoría son tan débiles que nadie los siente!", s: ["Países como Japón, Chile y México están en el borde de placas y tienen muchos terremotos.", "Por eso construyen edificios especiales, que se balancean sin caerse.", "Cuando un terremoto ocurre en el fondo del mar, puede crear olas gigantes llamadas tsunamis."], ex: { t: "Terremoto en la gelatina", m: "una fuente con gelatina firme, terrones de azúcar o bloques para armar, palillos", p: ["Construye casitas con terrones de azúcar o bloques encima de la gelatina.", "Mueve la fuente suavemente de un lado al otro, como un terremoto.", "¿Qué casitas se cayeron? Ahora prueba construcciones más anchas y bajas o con palillos cruzados. ¿Aguantan mejor?"] }, at: "Plan de seguridad", m: "papel, lápices de colores", p: ["Dibuja tu casa y marca el lugar más seguro de cada cuarto, como debajo de una mesa fuerte.", "Escribe las tres reglas para terremotos: agacharse, cubrirse la cabeza y sujetarse.", "Dibuja el sello del día 9 en el pasaporte."], q: "¿Cómo crees que se preparan las personas que viven donde hay terremotos?" } },

{ e: "🌋", art: { b: "🌋", s: ["🔥", "💨", "🏝️", "🪨"], c: ["#5A0B0B", "#E0402C"] },
pt: { h: "Leo desenhou um vulcão cuspindo lava laranja e perguntou se o Brasil tinha algum. “Hoje, nenhum ativo”, disse o vovô. “Mas a bela ilha de Fernando de Noronha nasceu de vulcões, há milhões de anos!” Nina pediu para fazer um vulcão na cozinha, e o vovô topou.", t: "Vulcões", f: "Em alguns lugares, a rocha derretida de dentro da Terra, o magma, sobe até a superfície por rachaduras. Quando ela sai, se chama lava. Os vulcões se formam ao longo de milhares de anos, com camadas de lava e cinzas que endurecem.", x: "Existem mais de mil vulcões que podem entrar em erupção no mundo. O Mauna Kea, no Havaí, medido desde a sua base no fundo do mar, é mais alto que o Monte Everest!", s: ["A lava pode chegar a mais de mil graus.", "A cinza dos vulcões, com o tempo, deixa a terra muito fértil para plantar.", "As ilhas do Havaí e de Fernando de Noronha foram formadas por vulcões."], ex: { t: "Vulcão de cozinha", m: "uma garrafinha, massinha ou terra para modelar o vulcão em volta, bicarbonato de sódio, vinagre, detergente, corante vermelho (opcional), uma bandeja", p: ["Coloque a garrafinha na bandeja e modele um vulcão de massinha ou terra ao redor dela.", "Coloque duas colheres de bicarbonato, um pouco de detergente e o corante dentro da garrafa.", "Despeje vinagre e afaste-se: a “lava” borbulha e escorre! A reação solta gás, como os gases que empurram o magma."] }, at: "Corte do vulcão", m: "papel, lápis de cor", p: ["Desenhe um vulcão cortado ao meio, mostrando a câmara de magma lá embaixo e o caminho até a cratera.", "Escreva os nomes: magma, cratera, lava e cinzas.", "Desenhe o selo do dia 10 no passaporte."], q: "Você gostaria de ver um vulcão de perto? De que distância?" },
en: { h: "Leo drew a volcano spitting orange lava and asked if Brazil had any. “Today, none that are active,” Grandpa said. “But the beautiful island of Fernando de Noronha was born from volcanoes millions of years ago!” Nina asked to make a volcano in the kitchen, and Grandpa agreed.", t: "Volcanoes", f: "In some places, melted rock from inside the Earth, called magma, rises to the surface through cracks. When it comes out, it's called lava. Volcanoes form over thousands of years from layers of lava and ash that harden.", x: "There are more than a thousand volcanoes in the world that could erupt. Mauna Kea, in Hawaii, measured from its base on the sea floor, is taller than Mount Everest!", s: ["Lava can be hotter than a thousand degrees Celsius.", "Over time, volcanic ash makes the soil very fertile for farming.", "The islands of Hawaii and Brazil's Fernando de Noronha were formed by volcanoes."], ex: { t: "Kitchen volcano", m: "a small bottle, play dough or soil to shape the volcano around it, baking soda, vinegar, dish soap, red food coloring (optional), a tray", p: ["Put the bottle on the tray and shape a volcano of play dough or soil around it.", "Put two spoonfuls of baking soda, a little dish soap and the coloring inside the bottle.", "Pour in vinegar and step back: the “lava” bubbles and flows! The reaction releases gas, like the gases that push magma up."] }, at: "Volcano cross-section", m: "paper, colored pencils", p: ["Draw a volcano cut in half, showing the magma chamber deep below and the path up to the crater.", "Label it: magma, crater, lava and ash.", "Draw the day 10 stamp in your passport."], q: "Would you like to see a volcano up close? How close?" },
es: { h: "Leo dibujó un volcán escupiendo lava naranja y preguntó si Brasil tenía alguno. “Hoy, ninguno activo”, dijo el abuelo. “¡Pero la hermosa isla de Fernando de Noronha nació de volcanes hace millones de años!” Nina pidió hacer un volcán en la cocina, y el abuelo aceptó.", t: "Volcanes", f: "En algunos lugares, la roca derretida del interior de la Tierra, el magma, sube a la superficie por grietas. Cuando sale, se llama lava. Los volcanes se forman a lo largo de miles de años, con capas de lava y cenizas que se endurecen.", x: "¡Hay más de mil volcanes en el mundo que pueden entrar en erupción! El Mauna Kea, en Hawái, medido desde su base en el fondo del mar, es más alto que el monte Everest.", s: ["La lava puede superar los mil grados.", "Con el tiempo, la ceniza de los volcanes deja la tierra muy fértil para cultivar.", "Las islas de Hawái y de Fernando de Noronha se formaron por volcanes."], ex: { t: "Volcán de cocina", m: "una botellita, plastilina o tierra para modelar el volcán alrededor, bicarbonato de sodio, vinagre, detergente, colorante rojo (opcional), una bandeja", p: ["Pon la botellita en la bandeja y modela un volcán de plastilina o tierra alrededor.", "Echa dos cucharadas de bicarbonato, un poco de detergente y el colorante dentro de la botella.", "Echa vinagre y aléjate: ¡la “lava” burbujea y chorrea! La reacción libera gas, como los gases que empujan el magma."] }, at: "Corte del volcán", m: "papel, lápices de colores", p: ["Dibuja un volcán cortado al medio, mostrando la cámara de magma abajo y el camino hasta el cráter.", "Escribe los nombres: magma, cráter, lava y cenizas.", "Dibuja el sello del día 10 en el pasaporte."], q: "¿Te gustaría ver un volcán de cerca? ¿A qué distancia?" } },
];
